-- ICDE F6 (real merge). Run ONCE in Snowsight as ACCOUNTADMIN before `./run_sf.sh f6`. Nine X-Small warehouses,
-- suspended, under CD_MONITOR; the scripts get USAGE/OPERATE/MODIFY/MONITOR only. Drop them after the pull (end of file).
USE ROLE ACCOUNTADMIN;
CREATE WAREHOUSE IF NOT EXISTS ICDE_HO_A WAREHOUSE_SIZE = XSMALL AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE COMMENT = 'ICDE F6 high overlap, member A';
CREATE WAREHOUSE IF NOT EXISTS ICDE_HO_B WAREHOUSE_SIZE = XSMALL AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE COMMENT = 'ICDE F6 high overlap, member B';
CREATE WAREHOUSE IF NOT EXISTS ICDE_HO_M WAREHOUSE_SIZE = XSMALL AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE COMMENT = 'ICDE F6 high overlap, merged';
CREATE WAREHOUSE IF NOT EXISTS ICDE_PO_A WAREHOUSE_SIZE = XSMALL AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE COMMENT = 'ICDE F6 partial overlap, member A';
CREATE WAREHOUSE IF NOT EXISTS ICDE_TT_A WAREHOUSE_SIZE = XSMALL AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE COMMENT = 'ICDE F6 turn-taking, member A';
CREATE WAREHOUSE IF NOT EXISTS ICDE_PO_B WAREHOUSE_SIZE = XSMALL AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE COMMENT = 'ICDE F6 partial overlap, member B';
CREATE WAREHOUSE IF NOT EXISTS ICDE_TT_B WAREHOUSE_SIZE = XSMALL AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE COMMENT = 'ICDE F6 turn-taking, member B';
CREATE WAREHOUSE IF NOT EXISTS ICDE_PO_M WAREHOUSE_SIZE = XSMALL AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE COMMENT = 'ICDE F6 partial overlap, merged';
CREATE WAREHOUSE IF NOT EXISTS ICDE_TT_M WAREHOUSE_SIZE = XSMALL AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE COMMENT = 'ICDE F6 turn-taking, merged';
ALTER WAREHOUSE ICDE_HO_A SET RESOURCE_MONITOR = CD_MONITOR;  ALTER WAREHOUSE ICDE_HO_B SET RESOURCE_MONITOR = CD_MONITOR;
ALTER WAREHOUSE ICDE_HO_M SET RESOURCE_MONITOR = CD_MONITOR;  ALTER WAREHOUSE ICDE_TT_A SET RESOURCE_MONITOR = CD_MONITOR;
ALTER WAREHOUSE ICDE_TT_B SET RESOURCE_MONITOR = CD_MONITOR;  ALTER WAREHOUSE ICDE_TT_M SET RESOURCE_MONITOR = CD_MONITOR;
ALTER WAREHOUSE ICDE_PO_A SET RESOURCE_MONITOR = CD_MONITOR;  ALTER WAREHOUSE ICDE_PO_B SET RESOURCE_MONITOR = CD_MONITOR;
ALTER WAREHOUSE ICDE_PO_M SET RESOURCE_MONITOR = CD_MONITOR;
GRANT USAGE, OPERATE, MODIFY, MONITOR ON WAREHOUSE ICDE_HO_A TO ROLE CD_ROLE;
GRANT USAGE, OPERATE, MODIFY, MONITOR ON WAREHOUSE ICDE_HO_B TO ROLE CD_ROLE;
GRANT USAGE, OPERATE, MODIFY, MONITOR ON WAREHOUSE ICDE_HO_M TO ROLE CD_ROLE;
GRANT USAGE, OPERATE, MODIFY, MONITOR ON WAREHOUSE ICDE_PO_A TO ROLE CD_ROLE;
GRANT USAGE, OPERATE, MODIFY, MONITOR ON WAREHOUSE ICDE_TT_A TO ROLE CD_ROLE;
GRANT USAGE, OPERATE, MODIFY, MONITOR ON WAREHOUSE ICDE_PO_B TO ROLE CD_ROLE;
GRANT USAGE, OPERATE, MODIFY, MONITOR ON WAREHOUSE ICDE_TT_B TO ROLE CD_ROLE;
GRANT USAGE, OPERATE, MODIFY, MONITOR ON WAREHOUSE ICDE_PO_M TO ROLE CD_ROLE;
GRANT USAGE, OPERATE, MODIFY, MONITOR ON WAREHOUSE ICDE_TT_M TO ROLE CD_ROLE;
SHOW WAREHOUSES LIKE 'ICDE_%';
-- After `./run_sf.sh pull6` has written sf/truth/f6_*.csv:
-- DROP WAREHOUSE ICDE_HO_A; DROP WAREHOUSE ICDE_HO_B; DROP WAREHOUSE ICDE_HO_M;
-- DROP WAREHOUSE ICDE_PO_A; DROP WAREHOUSE ICDE_PO_B; DROP WAREHOUSE ICDE_PO_M;
-- DROP WAREHOUSE ICDE_TT_A; DROP WAREHOUSE ICDE_TT_B; DROP WAREHOUSE ICDE_TT_M;
